// verbs, and English stopwords. Stripped before clustering so cards aren't grouped
// merely for both being autonomous handoffs (they ALL share that language).
const LOOP_STOPWORDS = new Set([
  "proposed", "handoff", "from", "autonomous", "run", "the", "a", "an", "and", "or",
  "of", "for", "to", "in", "on", "with", "this", "that", "review", "verify", "check",
  "task", "card", "please", "then", "is", "are", "be", "it", "its", "as", "at", "by",
]);
// Normalize a title to its significant token SET: lowercase, drop a leading
// "PROPOSED HANDOFF ..." prefix if present, split on non-alphanumerics (keeps
// hyphenated ids like rt-12 -> rt12), drop stopwords and 1-char noise.
function loopTokenSet(title) {
  let s = String(title || "").toLowerCase();
  s = s.replace(/^\s*proposed handoff[^:]*:?\s*/i, ""); // strip boilerplate lead-in
  const toks = s.replace(/[^a-z0-9]+/g, " ").split(/\s+/).filter(Boolean);
  const set = new Set();
  for (const t of toks) { if (t.length >= 2 && !LOOP_STOPWORDS.has(t)) set.add(t); }
  return set;
}
// Overlap of two token sets as a fraction of the SMALLER set (overlap coefficient,
// not Jaccard). Chosen deliberately: a terse card ("Attack RT-12/RT-13") and a
// verbose one ("Adversarially attack the RT-12 worker-identity binding and the
// RT-13 retarget gap under ARD 3.4") describe the SAME work but differ a lot in
// length -- Jaccard would score them low because the union is huge. Overlap-of-
