  const threshold = (opts && opts.threshold) || LOOP_ALERT_THRESHOLD;
  const simThreshold = (opts && opts.simThreshold) || 0.6; // >=60% of the smaller title's tokens shared
  const cards = (Array.isArray(tasks) ? tasks : [])
    .filter((t) => t && LOOP_SCAN_STATUSES.has(String(t.status || "").toLowerCase()))
    .map((t) => ({ id: String(t.id), title: String(t.title || ""), set: loopTokenSet(t.title) }))
    .filter((c) => c.set.size >= 2); // a card with <2 significant tokens can't be matched meaningfully
