  const artifacts = [{ type: "board_task", id: String(task && task.id || "") }];
  if (!change) return artifacts;
  if (change.branch) artifacts.push({ type: "git_branch", id: String(change.branch), ref: String(change.branch) });
  if (change.commitSha) artifacts.push({ type: "git_commit", id: String(change.commitSha) });
  if (change.pr && change.pr.number) artifacts.push({ type: "pull_request", id: String(change.pr.number), ref: String(change.pr.url || "") });
  return artifacts;
