  // reason, readiness still resolves to a definite answer and the guard clears.
  const bail = setTimeout(() => settle(false, "probe timed out after " + Math.round(ENGINE_READY_PROBE_MAX_MS / 1000) + "s"), ENGINE_READY_PROBE_MAX_MS);
  if (bail.unref) bail.unref();
