    const before = await gitJailedCommandResult(source, ["rev-parse", "HEAD"]);
    if (!before.ok || String(before.stdout).trim().toLowerCase() !== plan.headSha) return { error: "private branch changed before push" };
    tempRoot = fs.mkdtempSync(path.join(os.tmpdir(), "agenthost-git-transport-"));
    const bundle = path.join(tempRoot, "source.bundle");
    const jailBundle = "/agenthost-transport/source.bundle";
    const transport = path.join(tempRoot, "transport");
    // The bundle destination is a gate-created, one-use directory. It is
    // mounted only into this Git jail, so the agent workspace never receives a
    // host path and the clean transport can read the exact resulting artifact.
    const bundled = await gitJailedCommandResult(source, ["bundle", "create", jailBundle, plan.branch], {
      requiredRwBindAt: [{ src: tempRoot, dest: "/agenthost-transport" }],
    });
