const canonicalBoardSnapshotCache = canonicalBoard.createSingleFlightCache({ ttlMs: 1500 });
function invalidateCanonicalBoardSnapshot() {
  canonicalBoardSnapshotCache.invalidate();
}
const BOARD_RELATIONS_TIMEOUT_MS = 4_000;
const BOARD_RELATIONS_STDOUT_LIMIT = 1024 * 1024;
const BOARD_RELATIONS_STDERR_LIMIT = 16 * 1024;
const BOARD_RELATIONS_ROW_LIMIT = 25_000;
function boardRelationsProblem(value, dbPath) {
  let cause = String(value && value.message || value || "the read failed without a cause")
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .trim();
  for (const privatePath of [dbPath, HOME_DIR]) {
    if (privatePath) cause = cause.split(String(privatePath)).join("<private path>");
  }
  return "Hermes task links query failed: " + cause.slice(0, 300);
}
function loadCanonicalBoardRelations(taskIds) {
  const ids = Array.from(new Set((Array.isArray(taskIds) ? taskIds : []).map(String)));
  const visible = new Set(ids);
  const dbPath = path.join(HOME_DIR, ".hermes", "kanban.db");
  const unavailable = (cause) => ({
    available: false,
    byTask: {},
    problem: boardRelationsProblem(cause, dbPath),
  });
  const py = [
    "import sqlite3,sys,json",
    "try:",
    " ids=set(v for v in json.load(sys.stdin) if isinstance(v,str))",
    " c=sqlite3.connect('file:%s?mode=ro'%sys.argv[1],uri=True,timeout=2)",
    " rows=[]",
    " for i,row in enumerate(c.execute('select parent_id,child_id from task_links')):",
    "  if i >= int(sys.argv[2]): raise RuntimeError('task_links exceeds the bounded row limit')",
    "  p,ch=row",
    "  if p in ids and ch in ids: rows.append([p,ch])",
    " print(json.dumps({'ok':True,'rows':rows},separators=(',',':')))",
    "except Exception as e:",
    " print(json.dumps({'ok':False,'error':str(e)[:500]},separators=(',',':')))",
  ].join("\n");
  return new Promise((resolve) => {
    let out = "";
    let err = "";
    let outBytes = 0;
    let errBytes = 0;
    let settled = false;
    let child = null;
    let timer = null;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      resolve(value);
    };
    try {
      child = spawn("python3", ["-I", "-c", py, dbPath, String(BOARD_RELATIONS_ROW_LIMIT)], {
        env: gateChildEnv(process.env, { HOME: HOME_DIR }),
      });
      timer = setTimeout(() => {
        try { child.kill("SIGKILL"); } catch {}
        finish(unavailable(`the read exceeded ${BOARD_RELATIONS_TIMEOUT_MS}ms`));
      }, BOARD_RELATIONS_TIMEOUT_MS);
      timer.unref();
      child.stdout.on("data", (chunk) => {
        if (settled) return;
        outBytes += chunk.length;
        if (outBytes > BOARD_RELATIONS_STDOUT_LIMIT) {
          try { child.kill("SIGKILL"); } catch {}
          finish(unavailable("the read exceeded the 1 MiB output limit"));
          return;
        }
        out += chunk.toString();
      });
      child.stderr.on("data", (chunk) => {
        if (settled) return;
        errBytes += chunk.length;
        if (errBytes <= BOARD_RELATIONS_STDERR_LIMIT) err += chunk.toString();
      });
      child.on("error", (error) => finish(unavailable(error)));
      child.on("close", (code) => {
        if (settled) return;
        if (code !== 0) {
          finish(unavailable(err.trim() || `python3 exited ${code}`));
          return;
        }
        let parsed = null;
        try { parsed = JSON.parse(out); }
        catch (error) { finish(unavailable(`invalid JSON from the read: ${error.message}`)); return; }
        if (!parsed || parsed.ok !== true || !Array.isArray(parsed.rows)) {
          finish(unavailable(parsed && parsed.error || "the read returned an invalid result"));
          return;
        }
        const byTask = Object.fromEntries(ids.map((id) => [id, { parents: [], children: [] }]));
        const seen = new Set();
        for (const row of parsed.rows) {
          if (!Array.isArray(row) || row.length !== 2) continue;
          const parent = typeof row[0] === "string" ? row[0] : "";
          const childId = typeof row[1] === "string" ? row[1] : "";
          if (!visible.has(parent) || !visible.has(childId)) continue;
          const key = parent + "\u0000" + childId;
          if (seen.has(key)) continue;
          seen.add(key);
          byTask[parent].children.push(childId);
          byTask[childId].parents.push(parent);
        }
        for (const relation of Object.values(byTask)) {
          relation.parents.sort();
          relation.children.sort();
        }
        finish({ available: true, byTask });
      });
      child.stdin.end(JSON.stringify(ids));
    } catch (error) {
      finish(unavailable(error));
    }
  });
}
async function loadCanonicalBoardSnapshot() {
  return canonicalBoardSnapshotCache.get(async () => {
    const out = await hermesKanban(["list", "--json"], { caller: "canonicalBoard" });
    let tasks = [];
    let available = out !== null;
    if (out !== null) {
      try {
        const parsed = JSON.parse(out);
        if (!Array.isArray(parsed)) throw new Error("task list is not an array");
        tasks = parsed;
      } catch {
        available = false;
      }
    }
    if (tasks.length) {
      try { await attachLiveNotes(tasks); } catch {}
    }
    const sidecar = readChains();
    tasks = annotateBoardProblems(tasks, sidecar, Date.now());
    // WHICH GATE IS HOLDING EACH QUEUED CARD, so the board can offer the release.
    //
    // The classifier already runs on every queued card in the backlog digest and
    // its answer was thrown away before it reached the operator's screen. Without
    // it the board advertised assign + block on a held card and nothing that
    // moved it forward, so a gated card sat until someone read the source
    // (2026-08-12: `t_ccb561da` did exactly that, and the operator reported the
    // card had "no approve button").
    //
    // Only queued cards can be overridden -- the route itself refuses anything
    // else with `task_not_runnable` -- so computing it for other lanes would
    // advertise an action the server would reject.
    const gated = {};
    let gateProbeFailure = null;
    for (const task of tasks) {
      if (BOARD_COLUMN[String(task && task.status || "")] !== "queued") continue;
      let reason = null;
      try {
        reason = gitProposalGateReason(task, sset());
      } catch (e) {
        // FAIL TOWARD THE OPERATOR BEING ABLE TO ACT, and say so.
        //
        // The first cut here was `catch { reason = null; }`, which treats a
        // thrown classifier as "not gated" -- so the real gate still holds the
        // card while the board shows no way to release it. That is precisely the
        // stuck-card bug this commit exists to fix, recreated in the exception
        // path, and silently. (Kimi's HIGH finding on #395.)
        //
        // Offering the release costs nothing when it is wrong: the override
        // route re-validates the gate itself and refuses a stale one by name.
        // The server is the authority; this only decides what to SHOW.
        reason = "consequence";
        gateProbeFailure = gateProbeFailure || String((e && e.message) || e).slice(0, 160);
      }
      const issue = reason === "wording" ? "wording_gate" : reason === "consequence" ? "consequence_gate" : null;
      // An override already granted for THIS exact card is not a gate any more;
      // re-offering the button would invite a second click that changes nothing.
      if (issue && !sidecarOverride(sidecar, task, issue, Date.now())) gated[String(task.id)] = issue;
    }
    // Once per projection, not once per card: the cause must be readable without
    // the board flooding its own audit trail to say it (Rule 16, bounded).
    if (gateProbeFailure) {
      audit("board_gate_probe_failed", "the gate classifier threw while projecting the board, so held cards are"
        + " showing a release they may not need: " + gateProbeFailure);
    }
    const snapshot = canonicalBoard.projectCanonicalBoard(tasks, {
      awaiting: sidecar.humanReview || {},
      frozenIds: new Set(Object.keys(sidecar.frozen || {})),
      runningIds: claimRunningIds(tasks),
      gated,
      available,
    });
    snapshot.relations = available
      ? await loadCanonicalBoardRelations(snapshot.tasks.map((task) => task.id))
      : {
          available: false,
          byTask: {},
          problem: "Hermes task links query failed: the canonical task list was unavailable.",
        };
    return snapshot;
  });
}
async function loadCanonicalTaskDetails(taskId) {
  const out = await hermesKanban(["show", String(taskId), "--json"]);
  if (out === null) return null;
  let parsed = null;
  try { parsed = JSON.parse(out); } catch { return null; }
  return parsed && typeof parsed === "object" ? parsed : null;
}
