    const base = pull.json.base || {};
    const realHead = String(head.sha || "").toLowerCase();
    if (!GIT_SHA_RE.test(realHead)) {
      audit("review_failed", reviewer + " got no usable head sha for PR #" + prNumber + " from GitHub", undefined, reviewer, taskId);
      return sendJson(res, 502, { error: "GitHub returned no usable head sha for this pull request" });
    }
    // The branch was caller-asserted and the author engine is derived from it, so
    // a branch that is not this PR's head ref would attribute the review to the
    // wrong engine and let the identity check pass on a name nobody wrote.
    if (String(head.ref || "") !== branch) {
      audit("review_failed", reviewer + " submitted branch " + branch + " but PR #" + prNumber + " has head ref " + String(head.ref || "(none)"), undefined, reviewer, taskId);
      return sendJson(res, 409, { error: "pull request #" + prNumber + " is not on branch " + branch });
    }
    if (realHead !== headSha) {
      audit("review_head_stale", reviewer + " reviewed " + headSha.slice(0, 8) + " but PR #" + prNumber + " is at " + realHead.slice(0, 8), undefined, reviewer, taskId);
      return sendJson(res, 409, { error: "the reviewed head sha is not this pull request's current head (" + realHead + ") -- re-review at that commit" });
    }
